   if (e.y <= p.y && p.y < e.w) { // downward? standard
      float xint = e.x + (p.y-e.y)*(e.z-e.x)/(e.w-e.y);
      if (xint > p.x) { winding += (e.w > e.y) ? 1 : -1; inside=!inside; }
