    if (_cairo_vulkan_device == NULL)
	_cairo_vulkan_device = _cairo_vulkan_device_create ();

    if (_cairo_vulkan_device != NULL)
	_cairo_vulkan_device->ref_count++;

    CAIRO_MUTEX_UNLOCK (_cairo_vulkan_mutex);

    return _cairo_vulkan_device;
}

