    if (device != NULL && --device->ref_count == 0) {
	if (_cairo_vulkan_device == device)
	    _cairo_vulkan_device = NULL;
	destroy = TRUE;
    }

    CAIRO_MUTEX_UNLOCK (_cairo_vulkan_mutex);

    if (destroy)
	_cairo_vulkan_device_destroy (device);
}

