    if (surface->device == NULL || surface->fence == VK_NULL_HANDLE)
	return CAIRO_INT_STATUS_SUCCESS;

    result = vkWaitForFences (surface->device->device, 1, &surface->fence,
			      VK_TRUE, UINT64_MAX);
    if (result != VK_SUCCESS)
	return CAIRO_INT_STATUS_DEVICE_ERROR;

    return CAIRO_INT_STATUS_SUCCESS;
}

